import{_ as t,o as i,c as s,an as o}from"./chunks/framework.odgMDt1-.js";const h=JSON.parse('{"title":"Release notes","description":"","frontmatter":{},"headers":[],"relativePath":"release-notes.md","filePath":"release-notes.md","lastUpdated":null}'),a={name:"release-notes.md"};function l(r,e,n,p,d,b){return i(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="Release-notes" tabindex="-1">Release notes <a class="header-anchor" href="#Release-notes" aria-label="Permalink to &quot;Release notes {#Release-notes}&quot;">​</a></h1><p>Every release of this package is published as a GitHub release. The most recent are reproduced below, as they were written there.</p><h2 id="v1.0.0" tabindex="-1">v1.0.0 <a class="header-anchor" href="#v1.0.0" aria-label="Permalink to &quot;v1.0.0 {#v1.0.0}&quot;">​</a></h2><p>Released 2026-11-20. <a href="https://github.com/EpiAware/ScoringRules.jl/releases/tag/v1.0.0" target="_blank" rel="noreferrer">Read it on GitHub</a>.</p><p>First release: a Julia port of the R scoringRules package (version 1.1.3), with thanks to the authors of that package.</p><p><strong>Merged pull requests:</strong></p><ul><li><p>chore: auto-increment version to 0.1.1 (#1) (@github-actions[bot])</p></li><li><p>ci(deps): bump julia-actions/cache from 2 to 3 (#2) (@dependabot[bot])</p></li><li><p>ci(deps): bump actions/checkout from 4 to 7 (#3) (@dependabot[bot])</p></li><li><p>chore(deps): update JET requirement from 0.9, 0.10 to 0.9, 0.10, 0.11 (#7) (@dependabot[bot])</p></li><li><p>chore(deps): update DifferentiationInterfaceTest requirement from 0.9, 0.10 to 0.9, 0.10, 0.11 (#8) (@dependabot[bot])</p></li><li><p>ci(deps): bump the github-actions group across 1 directory with 9 updates (#24) (@dependabot[bot])</p></li><li><p>Add member weights to the sample CRPS and DSS scores (#26) (@sbfnk-bot)</p></li><li><p>style: fix comment indentation in docs_config.jl (#27) (@sbfnk-bot)</p></li><li><p>docs: drop R bug reports from the differences-from-R page (#37) (@sbfnk-bot)</p></li><li><p>Add the error-spread score ess_moments (#38) (@sbfnk-bot)</p></li><li><p>Add censored and conditional likelihood scores for ensemble forecasts (#39) (@sbfnk-bot)</p></li><li><p>Mirror R&#39;s quantile index fuzz in the sample quantile helper (#40) (@sbfnk-bot)</p></li><li><p>Return NaN from owcrps when no ensemble member has positive weight (#41) (@sbfnk-bot)</p></li><li><p>Return NaN from dss when the forecast variance does not exist (#42) (@sbfnk-bot)</p></li><li><p>Add member weights to vs, mmds and the weighted ensemble scores (#43) (@sbfnk-bot)</p></li><li><p>Add BoundaryMass wrapper exposing point-mass CRPS variants (#44) (@sbfnk-bot)</p></li><li><p>Add the pairwise weight matrix w_vs to twvs and owvs (#45) (@sbfnk-bot)</p></li><li><p>docs: add Related packages README section required by the QA standard (#49) (@sbfnk-bot)</p></li><li><p>chore: depend on registered EpiAwarePackageTools 0.3.0 instead of the git main pin (#50) (@sbfnk-bot)</p></li><li><p>chore(deps): bump the julia group across 1 directory with 3 updates (#51) (@dependabot[bot])</p></li><li><p>Add member weights to the sample log score (beyond R) (#52) (@sbfnk-bot)</p></li><li><p>Raise Distributions compat floor to 0.25.124 (#53) (@sbfnk-bot)</p></li><li><p>Real AD scenarios + AD-safe CRPS for beta_inc/gamma_inc families (#54) (@sbfnk-bot)</p></li><li><p>Enable org branding and add the CRPS logo (#56) (@sbfnk-bot)</p></li><li><p>Correct the README license badge to GPL-2.0-or-later (#58) (@sbfnk-bot)</p></li><li><p>ci: hand-apply the current managed template-sync and Register workflows (#59) (@sbfnk-bot)</p></li><li><p>docs: add Sam Abbott as an author and record ORCIDs in the citation metadata (#60) (@sbfnk-bot)</p></li><li><p>fix: run tests through TestItemRunner&#39;s public API (#61) (@sbfnk-bot)</p></li><li><p>chore: migrate the formatter from JuliaFormatter to Runic (#63) (@sbfnk-bot)</p></li><li><p>docs: correct the AD support map and name the real blockers (#64) (@sbfnk-bot)</p></li><li><p>ci(deps): bump the github-actions group with 7 updates (#65) (@dependabot[bot])</p></li><li><p>chore(deps): update EpiAwarePackageTools requirement from =0.3.0 to =0.3.0, 0.4 in the julia group (#66) (@dependabot[bot])</p></li><li><p>docs: scope the attribution request so divergence doesn&#39;t outdate it (#67) (@sbfnk-bot)</p></li><li><p>ci(deps): bump the github-actions group with 7 updates (#69) (@dependabot[bot])</p></li><li><p>fix: stub the AD backends tutorial around an Enzyme GC-rooting segfault (#71) (@sbfnk)</p></li><li><p>Re-apply the EpiAwarePackageTools managed standard (#74) (@sbfnk-bot)</p></li><li><p>Point release notes at GitHub releases (#76) (@sbfnk-bot)</p></li><li><p>Fix the Julia 1.13 resolve and the docs npm resolve (#97) (@sbfnk)</p></li><li><p>Re-apply the managed EpiAware standard (#99) (@sbfnk-bot)</p></li><li><p>chore(deps): update DocStringExtensions requirement from 0.9 to 0.9, 0.10 in the julia group across 1 directory (#100) (@dependabot[bot])</p></li><li><p>chore(deps): bump the julia-isolated group across 4 directories with 15 updates (#103) (@dependabot[bot])</p></li><li><p>Set the version to 1.0.0 (#104) (@sbfnk-bot)</p></li><li><p>Return the mean pinball loss from the multi-level quantile score (#106) (@sbfnk-bot)</p></li><li><p>chore(deps): update Mooncake requirement to 0.5.70 in /test/ADFixtures in the julia-isolated group across 1 directory (#107) (@dependabot[bot])</p></li><li><p>Check against R scoringRules master (#109) (@sbfnk-bot)</p></li><li><p>Score only the families R scoringRules scores (#111) (@sbfnk-bot)</p></li><li><p>Score a zero-scale normal forecast as R does (#114) (@sbfnk-bot)</p></li><li><p>Keep the logistic CRPS finite where R does (#115) (@sbfnk-bot)</p></li><li><p>Score a large-mean Poisson forecast as R does (#116) (@sbfnk-bot)</p></li><li><p>Score a truncated Student-t with a far bound as R does (#118) (@sbfnk-bot)</p></li><li><p>Reject the sample-score inputs R stops on (#120) (@sbfnk-bot)</p></li><li><p>Add R&#39;s smooth weight and chaining functions (#121) (@sbfnk-bot)</p></li><li><p>Re-apply the managed workflow standard (#122) (@sbfnk-bot)</p></li><li><p>Score a zero-bandwidth ensemble as point masses in logs and clogs, as R does (#124) (@sbfnk-bot)</p></li><li><p>Reject Inf and NaN in univariate sample scores, as R does (#125) (@sbfnk-bot)</p></li><li><p>Drop member weights from the sample log score, as in R (#126) (@sbfnk-bot)</p></li><li><p>Add a light-mode version of the logo (#128) (@sbfnk-bot)</p></li></ul><p><strong>Closed issues:</strong></p><ul><li><p>Student-t CRPS (and Beta/LogLogistic) aren&#39;t AD-differentiable — beta_inc/cdf(TDist) don&#39;t propagate dual numbers (#6)</p></li><li><p>Add member weights to the sample log and Dawid–Sebastiani scores (#9)</p></li><li><p>Quality-parity review vs the org standard (#10)</p></li><li><p>Gamma, GEV and Poisson crps are not ForwardDiff-differentiable (gamma_inc has no Dual method) (#11)</p></li><li><p>Branch protection (#14)</p></li><li><p>Sample quantile helper fuzz rule diverges from R at near-integer n*p (#28)</p></li><li><p>owcrps throws when no ensemble member has positive weight; R and the other ow* scores return NaN (#29)</p></li><li><p>dss error behaviour inconsistent when the forecast variance does not exist (#30)</p></li><li><p>Add the error-spread score (R ess_moments) (#31)</p></li><li><p>Add the censored likelihood score for samples (R clogs_sample) (#32)</p></li><li><p>Support member weights in vs, mmds, and the weighted ensemble scores (#33)</p></li><li><p>Support the pairwise weight matrix (w_vs) in twvs and owvs (#34)</p></li><li><p>Public entry points for the point-mass distribution variants (#35)</p></li><li><p>Upstream R scoringRules bugs found during validation (to report upstream) (#36)</p></li><li><p>Point the release-notes docs page at GitHub Releases (#47)</p></li><li><p>Template sync failed: managed infra has drifted (#68)</p></li><li><p>Template sync failed: managed infra has drifted (#73)</p></li><li><p>Template sync failed: managed infra has drifted (#82)</p></li><li><p>Release nudge: ScoringRules has 178 unreleased commit(s) on main (#83)</p></li><li><p>Release nudge: ScoringRules has 178 unreleased commit(s) on main (#96)</p></li><li><p>Release nudge: ScoringRules has 182 unreleased commit(s) on main (#101)</p></li><li><p>Template sync failed: managed infra has drifted (#110)</p></li></ul><p>Every release, including any older than those above, is listed on the <a href="https://github.com/EpiAware/ScoringRules.jl/releases" target="_blank" rel="noreferrer">releases page</a>.</p>',10)])])}const m=t(a,[["render",l]]);export{h as __pageData,m as default};
